using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using Frociart;
internal static class CodeTemplateCoreTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}static void Reject(Action action,string label){try{action();}catch(ArgumentException){checks++;return;}throw new Exception("Expected rejection: "+label);}
 static FlowSource.Program program=FlowSource.Compile(FlowPseudocode.Decode("FUNZIONE doppio(x: INTERO) -> INTERO r\nr=x*2\nFINE FUNZIONE\nLEGGI x\nSE x>0 ALLORA\nSTAMPA doppio(x)\nALTRIMENTI\nSTAMPA \"Altro 🐢\"\nFINE SE"));
 static FlowCodeTemplate Template(string body,string language="custom"){return FlowCodeTemplate.Create("Prova",language,"txt","Istruzioni",body);}
 static string Run(string body){return Template(body).Generate(program,null).Text.TrimEnd('\n');}
 static int Main(string[] args){try{
  Check(Run("Prima {{ project.title }} dopo").StartsWith("Prima "),"Scalar fields are interpolated");Check(Run("{% raw %}{{ ignored }} {% render nope x %}{% endraw %}")=="{{ ignored }} {% render nope x %}","Raw escapes never execute tags");Check(Run("a{# secret {{ignored}} #}b")=="ab","Comments are omitted");
  Check(Run("{% if true %}Sì{% else %}No{% endif %}|{% if false %}No{% else %}Sì{% endif %}")=="Sì|Sì","If and else");Check(Run("{% for item in program.main.notes %}bad{% else %}vuoto{% endfor %}")=="vuoto","Empty loop else");
  Check(Run("{{ 'a|b:c' | upper }}")=="A|B:C","Quoted pipe and colon are data");Check(Run("{{ false | not }}|{{ true | equals:true }}|{{ 2 | equals:2 }}|{{ null | default:'vuoto' }}")=="true|true|true|vuoto","Passive filters");
  Check(Run("{% for scope in program.scopes %}{{ loop.index }}-{{ loop.length }}-{{ loop.first }}-{{ loop.last }};{% endfor %}")=="1-2-true-false;2-2-false-true;","Loop metadata is scoped");
  Check(Run("{{ 'a}}b' }}")=="a}}b","Closing output delimiters inside quoted constants are data");
  Check(Run("{% require true | 'message %} still quoted' %}ok")=="ok","Closing tag delimiters inside quoted constants are data");
  Check(Run("{{ program.main.symbolNames | join:', ' }}").Contains("x"),"Join scalar lists from IR");
  string macro="{% macro expr e %}{% if e.isNumber %}{{ e.number }}{% else %}{% if e.isVariable %}{{ e.identifier }}{% else %}({% render expr e.children.0 %} {{ e.text }} {% render expr e.children.1 %}){% endif %}{% endif %}{% endmacro %}{% render expr program.functions.0.blocks.1.writes.0.value %}";
  Check(Run(macro).Contains(" * 2)"),"Recursive expression macro uses immutable IR");
  var mapped=Template("{{ program.main.blocks.1.text }}").Generate(program,null);Check(mapped.ForBlock(null,program.Scopes[0].Blocks[1].Id).Count==1,"Direct IR path retains origin");
  mapped=Template("{% for block in program.main.blocks %}{{ block.kind }}\n{% endfor %}").Generate(program,null);Check(program.Scopes[0].Blocks.All(b=>mapped.ForBlock(null,b.Id).Count==1),"Loop literals retain one origin per line");
  string original=program.Title;var injectionProgram=FlowSource.Compile(FlowPseudocode.Decode("STAMPA 1"));var doc=FlowPseudocode.Decode("STAMPA 1");doc.Title="{{ source }}{% render evil x %}";injectionProgram=FlowSource.Compile(doc);Check(Template("{{ project.title }}").Generate(injectionProgram,null).Text.TrimEnd('\n')==doc.Title,"Interpolated text is never reparsed as template instructions");
  foreach(var target in FlowSourceTarget.All){var source=target.Generate(program);var t=Template("{{ source }}",target.Id);var result=t.Generate(program,source);Check(result.Text==source.Text,"Identity template preserves complete source: "+target.Id);Check(result.Lines.Count==source.Lines.Count,"Identity template preserves lines: "+target.Id);foreach(var scope in program.Scopes)foreach(var block in scope.Blocks)Check(source.ForBlock(scope.Id,block.Id).Select(l=>l.Number).SequenceEqual(result.ForBlock(scope.Id,block.Id).Select(l=>l.Number)),"Identity mapping: "+target.Id);Check(FlowCodeTemplate.Parse(t.Text).Text==t.Text,"Canonical template round trip: "+target.Id);Reject(()=>t.Generate(program,null),"Missing base source");}
  foreach(string body in new[]{"{{ missing }}","{{ project.GetType }}","{{ project.title.ToString }}","{% include 'file' %}","{% render missing project %}","{% for i in project.title %}x{% endfor %}","{{ project | literal }}","{{ 1 | number:4 }}","{% if true %}","{% for a in program.scopes %}","{% raw %}","{{ 'unterminated }}","{{ 'x' | eval }}","{% require false | 'Spiegazione' %}","{% macro cycle p %}{% render cycle p %}{% endmacro %}{% render cycle program %}"})Reject(()=>Template(body).Generate(program,null),body);
  Reject(()=>Template("{{ source | upper }}","javascript").Generate(program,FlowJavaScript.Generate(program)),"Source filtering cannot break mapping silently");
  Reject(()=>Template("{% for loop in program.scopes %}{{loop.index}}{% endfor %}"),"Reserved loop metadata name");Reject(()=>Template("{{ program | count }}").Generate(program,null),"Invalid count cannot silently appear as zero");
  string encoded=Template("{{ project.title }}").Text;foreach(string bad in new[]{encoded.Replace("Version = 1","Version = 2"),encoded.Replace("Name = Prova","Name = Prova\nName = Altra"),encoded.Replace("Base = custom","Base = unavailable"),encoded.Replace("Extension = txt","Extension = ../exe"),encoded.Replace("Instructions = Istruzioni","Unknown = value"),encoded.Replace("Case Sensitive = true","Case Sensitive = yes"),encoded+"\ud800",new string('x',FlowCodeTemplate.MaxCharacters+1)})Reject(()=>FlowCodeTemplate.Parse(bad),"Malformed definition");
  Reject(()=>Template(String.Concat(Enumerable.Repeat("{% if true %}",65))+String.Concat(Enumerable.Repeat("{% endif %}",65))),"AST depth bound");Reject(()=>Template(String.Concat(Enumerable.Repeat("{{ 'a' }}",9000))),"AST node bound");Reject(()=>Template(String.Concat(Enumerable.Repeat("{% for scope in program.scopes %}",6))+"{{ source }}"+String.Concat(Enumerable.Repeat("{% endfor %}",6)),"javascript").Generate(program,FlowJavaScript.Generate(program)),"Generated size bound");
  Reject(()=>Template(String.Concat(Enumerable.Repeat("{% for scope in program.scopes %}",18))+"x"+String.Concat(Enumerable.Repeat("{% endfor %}",18))).Generate(program,null),"Operation budget stops exponential loops");
  Check(Run("{{ 'x' | identifier }} {{ '_u0078' | identifier }} {{ 'x' | identifier }}")=="user_x user__u005fu0078 user_x","Identifier encoding is stable and injective for encoded-looking names");
  string vector="["+String.Join(",",Enumerable.Range(1,256))+ "]";var large=FlowSource.Compile(FlowPseudocode.Decode(String.Join("\n",Enumerable.Range(0,150).Select(i=>"v="+vector))));Check(large.CanGenerate,"Owned high-expression fixture is valid");var light=Template("{{ program.scopes | count }} / {{ program.functions | count }} / {{ program.title }}").Generate(large,null);Check(light.Text.StartsWith("1 / 0 / "),"Title and counts do not materialize oversized IR trees");Check(Template("{{ program.main.blocks | count }}").Generate(large,null).Text.Trim()==large.Scopes[0].Blocks.Count.ToString(),"Block counts do not materialize unrelated expressions");Reject(()=>Template("{% for b in program.main.blocks %}{% if b.isProcess %}{% for e in b.writes.0.value.children %}{{ e.number }}{% endfor %}{% endif %}{% endfor %}").Generate(large,null),"Full expression traversal still enforces bounded data materialization");
  Console.WriteLine("CODE_TEMPLATE_CORE PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
